"""反三角函数：按完整转录与63张采样板书重写，明确各分支的区间。"""
def plan(example,check):
 result=dict(minutes=45,bvid='BV1uz421q7e8',
  summary='反函数要单值；反三角函数先查输入定义域，再查输出主值区间，复合消去必须保留区间。',
  board='arcsin：[-1,1]→[-π/2,π/2]；arccos：[-1,1]→[0,π]\narctan：R→(-π/2,π/2)；本课 arccot：R→(0,π)\nsin(arcsin u)=u（|u|≤1）；arcsin(sin θ)=θ 仅当 θ∈[-π/2,π/2]',
  visualization=dict(type='inverse-trig-principal'),
  text=[
   ('反函数不是倒数，先问是否单值','函数 y=f(x) 的反问题是由输出 y 唯一找回输入 x。x² 在整个实数轴上不能做到，例如 y=1 对应 ±1；限制 x≥0 后才有反函数 √y。严格单调足以保证单射，单调不减本身不够，例如常值函数仍会把不同输入映成同一输出。f⁻¹ 不是 1/f。把反函数也写作 y=f⁻¹(x) 后，两幅图像关于 y=x 对称；若保留 x=f⁻¹(y)，它与原来的 y=f(x) 只是同一关系的改写。'),
   ('主值区间让返回的角唯一','正弦在整个实数轴重复取值，因此先限制 θ∈[-π/2,π/2]，再定义反正弦。arcsin 输入是 [-1,1] 中的正弦值，输出是 [-π/2,π/2] 中唯一的角；它严格递增、为奇函数、有界而不周期。arcsin(√3/2)=π/3，arcsin(-1/2)=-π/6。所有角统一用弧度。'),
   ('嵌套先检查里面，再谈消去','arcsin(√2)、arcsin(-π/3)、sin(arcsin 2) 在实数范围无意义；arcsin(sin 2) 则有意义，因为内层 sin 2 一定在 [-1,1] 中。但它不等于 2：2 超出反正弦的值域，正确结果是 π-2。sin(arcsin u)=u 要求 |u|≤1；反过来 arcsin(sin θ)=θ 还要求 θ 处在主值区间。'),
   ('非主值分支先搬角，再反解','求 y=sin x 在 [π/2,3π/2] 上的反函数，令 t=π-x∈[-π/2,π/2]，则 sin t=sin x=y，故 t=arcsin y，x=π-arcsin y，y∈[-1,1]。若原区间改为 [2π,5π/2]，则令 t=x-2π∈[0,π/2]，反解为 x=2π+arcsin y，此时输入 y 只在 [0,1]。反解后要回查原来指定的角区间与值域，不能只搬公式。'),
   ('反余弦的性质与互余关系','arccos 的定义域是 [-1,1]，值域是 [0,π]，严格递减、非奇非偶、有界而不周期。由 cos(π-α)=-cos α，且 π-arccos u 仍在 [0,π]，可证 arccos(-u)=π-arccos u。又 π/2-arccos u∈[-π/2,π/2]，其正弦为 u，所以 arcsin u+arccos u=π/2。两式均要求 |u|≤1。只画锐角三角形不能单独证明负 u 的情形，主值区间论证覆盖全部定义域。'),
   ('反正切的开区间与分段图像','arctan 的定义域是全体实数，值域为开区间 (-π/2,π/2)，严格递增、为奇函数、有界而不周期。arctan 1=π/4，arctan(-√3)=-π/3；当 x→±∞ 时分别趋于 ±π/2，但有限输入不会取到这两个端点。arctan(tan θ) 在 θ=kπ±π/2 处无定义；若 kπ-π/2<θ<kπ+π/2，则返回 θ-kπ，形成以 π 为周期的开端点斜线段。复合函数周期性不能误加到 arctan 本身。'),
   ('反余切与倒数关系先声明约定','本课与源视频采用 arccot 值域 (0,π) 的约定，故 arccot x=π/2-arctan x，对所有实数成立；它严格递减、非奇非偶、有界而不周期。arccot(-x)=π-arccot x。对 x≠0，arctan x+arctan(1/x) 在 x>0 时为 π/2，在 x<0 时为 -π/2；相应地 arctan(1/x) 在 x>0 时等于 arccot x，在 x<0 时等于 arccot x-π。'),
   ('适用条件与易错边界','实数反三角函数先查内层定义域，再查外层输出区间。arcsin 与 arccos 可取各自主值端点；arctan 与本课 arccot 不能取端点。arccos 不是偶函数；arctan 有界不表示能取到界。三角与反三角的消去顺序不同，所需条件也不同。'),
  ],
  ex=example('计算 arccos(cos(11π/6))。','π/6。',[('先检查输出范围','arccos 只能返回 [0,π] 中的角，因此 11π/6 不能直接成为答案。'),('换成同余弦的主值角','cos(11π/6)=cos(-π/6)=cos(π/6)。'),('确认范围后消去','π/6∈[0,π]，故 arccos(cos(π/6))=π/6。')]),
  stages=[
   ('先找角的返回范围','“反”不是把符号倒过来就完事。输入同一个正弦值，整条数轴上可能找出无穷多个角，我们却只允许函数返回一个。先把主值区间写在纸边上。白厄，再告诉我：那个角的正弦对了，是否就一定能交卷？'),
   ('搬到主值区间再消去','别急着划掉反余弦和余弦。十一派除以六，已经超出了允许返回的范围。先找一个余弦值相同、又落在零到派之间的角，再消去。每一次变换，你都得同时交代函数值和区间；只顾其中一个，仍然不能成立。'),
   ('分清分支与端点','现在换你处理。正切没有定义的端点，反正切也不能替它补上；反余弦不是偶函数，负号不能随手扔掉。做完数值题，再把指定区间的反函数代回去检查。能把这些条件解释清楚，才算掌握了反解。'),
  ],
  sides={
   'hyacine':'我们给每个返回角留一个小位置吧：反正弦在负二分之派到二分之派之间，反余弦在零到派之间。先找熟悉的三角值，再核对角有没有回到自己的区间。做错也没关系，把漏看的区间补上，就能继续推下去了。',
   'castor':'请先看范围。反余弦的一不能与负一混同：前者为零，后者为派。余弦是偶函数，反余弦不是。',
   'phainon':'我刚找到一个正弦值一样的角，已经想举手了。结果老师指了指区间——走到别的分支上去了！这回我先把允许返回的位置圈出来，再把角搬回来。你看我这次是不是终于站对地方了？',
  },
  checks=[
   check('guided-inverse-unique',0,'f(x)=x² 若不限制实数 x，为什么不能直接把“±√y”当一个反函数？',['每个输出 y 都没有原输入','同一个 y=1 对应两个 x，不能唯一返回','反函数的输出不允许为负数'],1,'反函数也必须单值。限制 x≥0 后可返回 √y；限制 x≤0 则可返回 -√y，是两种不同的限定。'),
   check('guided-nested-domain',0,'arcsin(sin 2) 与 sin(arcsin 2)，哪项检查顺序有依据？',['两个符号都会消去，所以都等于 2','前者有意义；后者内层 arcsin 2 在实数范围无定义','两式都无意义，因为 2>1'],1,'前者先算 sin 2，结果在 [-1,1] 中；后者先算 arcsin 2，定义域检查已经失败。'),
   check('guided-return-angle',1,'为什么 arccos(cos(11π/6)) 不能直接写 11π/6？',['因为余弦只允许输入 [0,π]','因为 arccos 的返回角必须在 [0,π]，原角超出范围','因为 11π/6 的余弦无定义'],1,'余弦可接受此角；受到限制的是反余弦的输出。先换成同余弦的主值角 π/6。'),
   check('guided-nonprincipal-branch',1,'y=sin x，x∈[π/2,3π/2]。把角搬入主值区间的哪种操作正确？',['t=π-x，sin t=y，故 x=π-arcsin y','不管区间，直接写 x=arcsin y','把 x 的区间删掉即可'],0,'π-x 落在 [-π/2,π/2]，因此可以反解；所得 x 又回到原来的 [π/2,3π/2]。'),
   check('guided-shifted-range',1,'若原函数改为 y=sin x，x∈[2π,5π/2]，逆函数 x=2π+arcsin y 的输入范围应是什么？',['[-1,1]，任何正弦逆函数都相同','[0,1]，须用原区间实际覆盖的正弦值','全体实数'],1,'该区间的正弦从 0 增至 1。若误纳 y<0，逆解会跑到 2π 左边，超出原区间。'),
   check('guided-tan-endpoint',2,'arctan(tan(π/2)) 可以怎样处理？',['直接消去，得到 π/2','先代入 arctan 的渐近线，所以等于 π/2','原式无定义，因为内层 tan(π/2) 无定义'],2,'内层先通过定义域检查，才能谈复合函数。趋近端点的极限也不能替代端点函数值。'),
   check('guided-arccos-not-even',2,'有人把 arccos(-1) 写成 arccos 1。用哪条依据纠正？',['余弦是偶函数，所以这一步成立','[0,π] 中余弦为 -1 的角是 π，为 1 的角是 0','反余弦总是奇函数，因此结果为负数'],1,'arccos 非奇非偶。应使用 arccos(-u)=π-arccos u，而不是把原函数的偶性搬过来。'),
   check('guided-reciprocal-sign',2,'x=-1 时，arctan x+arctan(1/x) 是多少？',['π/2，与 x 正负无关','0，因为两个角互为相反数','-π/2，两项都等于 -π/4'],2,'倒数保留了负号，两项都在负的反正切主值区间，不能套 x>0 时的互余结论。'),
  ],
  extra=[
   example('比较 arcsin(sin 2) 与 sin(arcsin 2)（实数范围，角用弧度）。','前者等于 π-2，后者无定义。',[('先检查内层','sin 2∈[-1,1]；而 arcsin 2 无定义。'),('选主值角','π/2<2<π，且 sin 2=sin(π-2)。'),('核对范围','0<π-2<π/2，故 arcsin(sin 2)=π-2。')]),
   example('求 y=sin x 在 [π/2,3π/2] 上的反函数。','x=π-arcsin y，y∈[-1,1]；换字母后 g(u)=π-arcsin u。',[('搬角入主值区间','令 t=π-x，得 t∈[-π/2,π/2]。'),('保留函数值','sin t=sin(π-x)=sin x=y，故 t=arcsin y。'),('返回并验域','x=π-arcsin y。y∈[-1,1] 时，x 正好覆盖 [π/2,3π/2]。')]),
   example('求 y=sin x 在 [2π,5π/2] 上的反函数。','x=2π+arcsin y，y∈[0,1]。',[('先确定原值域','该段正弦从 0 增至 1，故逆函数输入为 [0,1]。'),('平移到主值区间','t=x-2π∈[0,π/2]，sin t=sin x=y。'),('反解并验算','t=arcsin y，故 x=2π+arcsin y，仍在原指定区间。')]),
   example('计算 arcsin(sin(5π/6))。','π/6。',[('范围先行','5π/6 不在 [-π/2,π/2]，不能直接消去。'),('保持正弦值','sin(5π/6)=sin(π/6)=1/2。'),('选择唯一主值','π/6 在反正弦值域内，故答案为 π/6。')]),
   example('证明 cos(arcsin u)=√(1-u²)，u∈[-1,1]。','取非负根 √(1-u²)，不是任取正负。',[('引入角及范围','设 α=arcsin u，则 α∈[-π/2,π/2]，sin α=u。'),('使用恒等式','cos²α=1-sin²α=1-u²。'),('用范围确定符号','在该主值区间 cos α≥0，故 cos α=√(1-u²)，端点也成立。')]),
   example('化简 arctan(tan θ)，并说明定义域、周期。','若 kπ-π/2<θ<kπ+π/2（k∈Z），则值为 θ-kπ；周期为 π，端点无定义。',[('排除原式无定义点','θ≠π/2+kπ。为所在开区间选 k，令 t=θ-kπ。'),('搬入反正切主值','t∈(-π/2,π/2)，且 tan θ=tan t。'),('消去并看重复','arctan(tan t)=t=θ-kπ；每段斜线按 π 重复，两个端点都挖去。')]),
   example('证明 arctan x+arctan(1/x) 的分段公式（x≠0）。','x>0 时为 π/2，x<0 时为 -π/2。',[('先看正数','x>0 时令 α=arctan x∈(0,π/2)，则 tan(π/2-α)=1/x，且补角仍在主值区间。'),('得到正数结论','arctan(1/x)=π/2-arctan x，故和为 π/2。'),('由奇性覆盖负数','x<0 时令 v=-x>0，两项分别取负，和为 -π/2；x=0 时倒数无定义。')]),
   example('化简 F(θ)=arcsin(sin θ)，θ∈R。','在 kπ-π/2≤θ≤kπ+π/2 上，F(θ)=(-1)^k(θ-kπ)，k∈Z；周期 2π。',[('先搬入主值区间','令 t=θ-kπ∈[-π/2,π/2]。'),('利用正弦平移与奇性','sin θ=(-1)^k sin t，故 arcsin(sin θ)=(-1)^k t。'),('检查接缝与周期','邻段端点的表达式取同一值，故端点可保留；图像呈连续三角波，按 2π 重复。')]),
  ],
  formulas=['实数 arcsin 输入须在 [-1,1]；返回角在 [-π/2,π/2]','t=π-x；sin(π-x)=sin x；x=π-arcsin y','t=x-2π∈[0,π/2]；y∈[0,1]','sin(5π/6)=sin(π/6)；arcsin(1/2)=π/6','sin²α+cos²α=1；α∈[-π/2,π/2] ⇒ cos α≥0','θ≠π/2+kπ；arctan(tan θ)=θ-kπ 于对应开区间','x>0：和=π/2；x<0：和=-π/2；x≠0','θ∈[kπ-π/2,kπ+π/2]：F(θ)=(-1)^k(θ-kπ)'],
  primary_check_url='https://openstax.org/books/calculus-volume-1/pages/1-4-inverse-functions')
 return result
